// filters that are set: the partial open index for the default tab, the started or changed index for a range, the
// trigram indexes for text, the jsonb_path_ops index for = label Matchers, the unique (org_id, number) for #N. The time
// range selects lifetimes that overlap it — created_at < to AND (resolved_at IS NULL OR resolved_at >= from), written
// with the status that the CHECK ties to resolved_at, so that the open index and alert_groups_resolved_idx serve it —
// and is ignored for a number. Label Matchers other than = with a value are matched in Go on common_labels, after
// these conditions; urgency and the newer open Alert Group are derived as in GetGroup. The Owner filter, with
// @owner_set, selects the Alert Groups the User @owner_id owns, or nobody owns when it is null. The Delivery problem
// (C-13.FR-12) and the next notice (C-17.FR-9) are derived as in GetGroup; @unclaimed selects the Unclaimed Alert Groups
// or the others (C-09.FR-13).
// ListGroupsStartedDesc reads a batch of the Alert Group list, newest start first, after the cursor when given.
func (q *Queries) ListGroupsStartedDesc(ctx context.Context, arg ListGroupsStartedDescParams) ([]ListGroupsStartedDescRow, error) {
	rows, err := q.db.Query(ctx, listGroupsStartedDesc,
		arg.OrgID,
		arg.Statuses,
		arg.Number,
		arg.RangeTo,
		arg.RangeFrom,
		arg.RouteIds,
		arg.IntegrationIds,
		arg.Severities,
		arg.Urgent,
		arg.ResolvedBy,
		arg.ResolveReason,
		arg.Reopened,
		arg.OwnerSet,
		arg.OwnerID,
		arg.TeamSet,
		arg.TeamIds,
		arg.SnoozedNoEnd,
		arg.DeliveryProblem,
		arg.Unclaimed,
		arg.Contains,
		arg.Pattern,
		arg.AfterAt,
		arg.AfterID,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListGroupsStartedDescRow{}
	for rows.Next() {
		var i ListGroupsStartedDescRow
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.Number,
			&i.Title,
			&i.Summary,
			&i.Status,
			&i.SeverityLevel,
			&i.Urgent,
			&i.CommonLabels,
			&i.IntegrationIds,
			&i.ReopenCount,
			&i.FiringAlertCount,
			&i.ResolvedAlertCount,
			&i.ResolvedAt,
			&i.ResolvedByKind,
			&i.ResolvedByUserID,
			&i.ResolvedByServiceAccountID,
			&i.ResolveReason,
			&i.ResolveReasonText,
			&i.CreatedAt,
			&i.LastChangedAt,
			&i.RoutePublicID,
			&i.RouteName,
			&i.OwnerUserID,
			&i.SnoozeUntil,
			&i.SnoozedByUserID,
			&i.SnoozedByServiceAccountID,
			&i.NewerPublicID,
			&i.NewerNumber,
			&i.RouteDeleted,
			&i.DeliveryProblem,
			&i.Unclaimed,
			&i.NextNoticeKind,
			&i.NextNoticeAt,
			&i.ReminderPending,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

