const lockRoutes = `-- name: LockRoutes :many
SELECT id, public_id, is_default, minimum_severity, group_key, reopen_window_seconds, grace_period_seconds,
       urgent_rise_removes_ack
FROM routes
WHERE org_id = $1 AND id = ANY($2::bigint[]) AND deleted_at IS NULL
ORDER BY id
FOR SHARE
`

type LockRoutesParams struct {
	OrgID int64
	Ids   []int64
}

type LockRoutesRow struct {
	ID                   int64
	PublicID             string
	IsDefault            bool
	MinimumSeverity      string
	GroupKey             []string
	ReopenWindowSeconds  int64
	GracePeriodSeconds   int64
	UrgentRiseRemovesAck bool
}

// LockRoutes locks the Routes that are not deleted FOR SHARE before grouping creates or joins an Alert Group on
// them, in id order: a deletion, which locks its Route FOR NO KEY UPDATE and then counts the open Alert Groups, waits
// for the Snapshot, or commits first and leaves the Route out of the result.
func (q *Queries) LockRoutes(ctx context.Context, arg LockRoutesParams) ([]LockRoutesRow, error) {
	rows, err := q.db.Query(ctx, lockRoutes, arg.OrgID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LockRoutesRow{}
	for rows.Next() {
		var i LockRoutesRow
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.IsDefault,
			&i.MinimumSeverity,
			&i.GroupKey,
			&i.ReopenWindowSeconds,
			&i.GracePeriodSeconds,
			&i.UrgentRiseRemovesAck,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

